    String string2 = this.prefs.getString("signing_key", null);
    String str3 = getBaseUrl() + "/api/v1/observers/sms";
    if (j <= 0) {
        try {
            j = System.currentTimeMillis();
        } catch (Exception e) {
            Log.e(TAG, "sendSms error: " + e.getMessage(), e);
            return false;
        }
